"""
    Turn an environment variable into a yaml key

    Keys in YAML files are generally lower case and use dashes instead of
    underscores. This isn't a universal rule, though, so we'll have to
    either change the keys to conform to this, or have some way of indicating
    this from the environment.
    """
def _make_yaml_key(s: Any) -> object {
    return s.lower().replace("_", "-");
}

"""Recursive function to annotate each node with the count of all
    of it's descendants, as well as the count of all sibling comments plus
    their children, made after each node.
    """
def annotate_counts(`node: Any) -> object {
    `node['reply_count'] = 0;
    if not `node['replies'] {
        return 1;
    } else {
        for r in `node['replies'] {
            `node['reply_count'] += annotate_counts(r);
        }
        after_count = 0;
        for r in reversed(`node['replies']) {
            r['after_count'] = after_count;
            after_count += r['reply_count'] + 1;
        }
        return (`node['reply_count'] + 1);
    }
}

